#!/usr/bin/env bash
# .env_sync.sh - Environment variable sync utility

set -euo pipefail

# ─── Configuration ────────────────────────────────────────────────────────────
ENV_FILE="${ENV_FILE:-.env}"
BACKUP_DIR="${BACKUP_DIR:-.env_backups}"
TIMESTAMP=$(date +"%Y%m%d_%H%M%S")

# ─── Helpers ──────────────────────────────────────────────────────────────────
log()  { echo "[env_sync] $*"; }
warn() { echo "[env_sync] WARN: $*" >&2; }
die()  { echo "[env_sync] ERROR: $*" >&2; exit 1; }

# ─── Functions ────────────────────────────────────────────────────────────────

# Load variables from .env into the current shell environment
load_env() {
  [[ -f "$ENV_FILE" ]] || die "No $ENV_FILE file found."
  log "Loading variables from $ENV_FILE..."
  set -a
  # shellcheck disable=SC1090
  source "$ENV_FILE"
  set +a
  log "Done."
}

# Export all currently set env vars to .env (overwrites)
export_env() {
  log "Exporting current environment to $ENV_FILE..."
  printenv | sort > "$ENV_FILE"
  log "Exported to $ENV_FILE."
}

# Backup the current .env file
backup_env() {
  [[ -f "$ENV_FILE" ]] || die "No $ENV_FILE to back up."
  mkdir -p "$BACKUP_DIR"
  local dest="$BACKUP_DIR/.env.$TIMESTAMP"
  cp "$ENV_FILE" "$dest"
  log "Backup saved to $dest"
}

# Show diff between current shell env and .env file
diff_env() {
  [[ -f "$ENV_FILE" ]] || die "No $ENV_FILE file found."
  log "Diffing current environment against $ENV_FILE..."
  diff <(printenv | sort) <(sort "$ENV_FILE") || true
}

# Print usage
usage() {
  cat <<EOF
Usage: .env_sync.sh <command>

Commands:
  load      Load variables from $ENV_FILE into current shell
  export    Export current environment to $ENV_FILE
  backup    Backup current $ENV_FILE to $BACKUP_DIR/
  diff      Show diff between shell env and $ENV_FILE
  help      Show this help message

Environment:
  ENV_FILE      Path to .env file (default: .env)
  BACKUP_DIR    Path to backup directory (default: .env_backups)
EOF
}

# ─── Entry Point ──────────────────────────────────────────────────────────────
case "${1:-help}" in
  load)   load_env ;;
  export) export_env ;;
  backup) backup_env ;;
  diff)   diff_env ;;
  help|--help|-h) usage ;;
  *) warn "Unknown command: $1"; usage; exit 1 ;;
esac
